class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        n = len(nums)
        pref = [0] * n
        lastEven = 0
        lastOdd = 0

        pref[0] = nums[0]

        i = 0
        while i < n - 1:
            if nums[i] % 2 == 1:
                pref[i + 1] = pref[lastEven] + nums[i + 1] - ((nums[lastEven] + nums[i + 1]) % 2) * x
            else:
                pref[i + 1] = max(pref[i + 1], pref[lastOdd] + nums[i + 1] - ((nums[lastOdd] + nums[i + 1]) % 2) * x)

            if nums[i + 1] % 2 == 1:
                lastOdd = i + 1
            else:
                lastEven = i + 1

            i += 1

        return max(pref)
